for tz in UTC Asia/Tokyo Pacific/Honolulu America/Chicago; do TZ=$tz node --input-type=module -e '
import { checkSms } from "./bot.mjs";
const m = (kind, o = {}) => ({ kind, body: "hi", to: { phone: "+13125550142", timeZone: "America/Chicago", marketingConsent: true, optedOutAt: null, ...o } });
const at = (iso) => new Date(iso);
const cases = [
  [m("marketing"), "2026-10-23T13:00:00Z", {allowed:true, reason:null}],                 // 08:00 CDT
  [m("marketing"), "2026-10-23T12:59:00Z", {allowed:false, reason:"outside_marketing_hours"}], // 07:59
  [m("marketing"), "2026-10-24T02:59:00Z", {allowed:true, reason:null}],                 // 20:59 CDT
  [m("marketing"), "2026-10-24T03:00:00Z", {allowed:false, reason:"outside_marketing_hours"}], // 21:00
  [m("marketing"), "2026-03-08T13:00:00Z", {allowed:true, reason:null}],                 // 08:00 CDT after spring-forward
  [m("marketing"), "2026-10-23T06:00:00Z", {allowed:false, reason:"outside_marketing_hours"}], // 01:00
  [m("marketing", {marketingConsent:false}), "2026-10-23T18:00:00Z", {allowed:false, reason:"no_marketing_consent"}],
  [m("marketing", {marketingConsent:undefined}), "2026-10-23T18:00:00Z", {allowed:false, reason:"no_marketing_consent"}],
  [m("marketing", {optedOutAt:"2026-10-01T10:00:00Z"}), "2026-10-23T18:00:00Z", {allowed:false, reason:"opted_out"}],
  [m("transactional", {optedOutAt:"2026-10-01T10:00:00Z"}), "2026-10-23T18:00:00Z", {allowed:false, reason:"opted_out"}],
  [m("marketing", {optedOutAt:"yesterday"}), "2026-10-23T18:00:00Z", {allowed:false, reason:"invalid_opt_out_timestamp"}],
  [m("marketing", {optedOutAt:undefined}), "2026-10-23T18:00:00Z", {allowed:false, reason:"opt_out_status_unknown"}],
  [m("marketing", {timeZone:"Mars/Olympus"}), "2026-10-23T18:00:00Z", {allowed:false, reason:"invalid_time_zone"}],
  [m("transactional"), "2026-10-24T08:00:00Z", {allowed:true, reason:null}],           // 03:00 local, transactional allowed
  [m("transactional", {marketingConsent:false}), "2026-10-23T18:00:00Z", {allowed:true, reason:null}],
  [m("promo"), "2026-10-23T18:00:00Z", {allowed:false, reason:"invalid_message"}],
  [m("marketing", {phone:"3125550142"}), "2026-10-23T18:00:00Z", {allowed:false, reason:"invalid_recipient"}],
  [m("marketing"), "not a date", {allowed:false, reason:"invalid_now"}],
];
let bad = 0;
for (const [msg, now, want] of cases) {
  const d = typeof now === "string" && now.startsWith("not") ? now : at(now);
  const got = checkSms(msg, d);
  if (JSON.stringify(got) !== JSON.stringify(want)) { bad++; console.log("FAIL", now, msg.kind, JSON.stringify(got), "want", JSON.stringify(want)); }
}
const single = checkSms(m("marketing"), at("2026-10-23T18:00:00Z"));
console.log(process.env.TZ, "cases", cases.length, "failures", bad, "sample", JSON.stringify(single));
' ; done

